class Solution:
    def subarrayBitwiseORs(self, arr: List[int]) -> int:
        seen = set()
        for i in range(len(arr)):
            cur = 0
            for j in range(i, len(arr)):
                cur |= arr[j]
                seen.add(cur)
        return len(seen)

