class Solution {
public:
    int subarrayBitwiseORs(vector<int>& arr) {
        unordered_set<int> seen;
        for (int i = 0; i < (int)arr.size(); i++) {
            int cur = 0;
            for (int j = i; j < (int)arr.size(); j++) {
                cur |= arr[j];
                seen.insert(cur);
            }
        }
        return seen.size();
    }
};

