class Solution {
public:
    int subarrayBitwiseORs(vector<int>& arr) {
        unordered_set<int> ans, cur;
        for (int x : arr) {
            unordered_set<int> next;
            next.insert(x);
            for (int v : cur) next.insert(v | x);
            cur = move(next);
            ans.insert(cur.begin(), cur.end());
        }
        return ans.size();
    }
};

