class Solution {
    public int subarrayBitwiseORs(int[] arr) {
        Set<Integer> ans = new HashSet<>(), cur = new HashSet<>();
        for (int x : arr) {
            Set<Integer> next = new HashSet<>();
            next.add(x);
            for (int v : cur) next.add(v | x);
            cur = next;
            ans.addAll(next);
        }
        return ans.size();
    }
}

